    validate("validate_decode_messages_missing",
             object({{"model", str("claude-3-5-sonnet")}}));
    validate("validate_decode_part_type_missing",
             object({{"model", str("claude-3-5-sonnet")},
                     {"messages",
                      array({object({{"role", str("user")},
                                     {"content",
                                      array({object({{"text", str("hi")}})})}})})}}));
