    auto base_value = [&](const std::string& key) -> json::Value {
        for (const auto& [member, value] : kBase) {
            if (member == key) return value;
        }
        fail("base key missing: " + key);
    };
    // Python copy.deepcopy(BASE) + dict update: base order, in-place replacement,
    // unknown keys appended after the snapshot in override order.
    auto snapshot = [&](std::vector<std::pair<std::string, json::Value>> overrides) {
        std::vector<std::pair<std::string, json::Value>> members = kBase;
        for (auto& [key, value] : overrides) {
            bool replaced = false;
            for (auto& member : members) {
                if (member.first == key) {
                    member.second = std::move(value);
                    replaced = true;
                    break;
                }
            }
            if (!replaced) members.emplace_back(key, std::move(value));
        }
        return object(std::move(members));
    };
    // Python write(): {"op", "settings"} then the remaining kwargs in call order.
    auto case_obj = [&](const char* op_name,
                        std::vector<std::pair<std::string, json::Value>> overrides,
                        std::vector<std::pair<std::string, json::Value>> fields) {
        std::vector<std::pair<std::string, json::Value>> members = {
            {"op", str(op_name)}, {"settings", snapshot(std::move(overrides))}};
        for (auto& [key, value] : fields) members.emplace_back(key, std::move(value));
        return object(std::move(members));
    };

